import chess, chess.engine
e = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
e.configure({"Threads": 4, "Hash": 2048})
board = chess.Board("r1bqkb1r/p4ppp/2p5/n2np1N1/7P/3B4/PPPP1PP1/RNBQK2R b KQkq - 0 9")
def sc(i): return i["score"].white().score(mate_score=10000)
b=board.copy(); b.push_uci("f8c5")
for d in (14,18,21):
    info=e.analyse(b, chess.engine.Limit(depth=d), multipv=4)
    print("=== Bc5 d",d, flush=True)
    for inf in info: print("  ", sc(inf), [x.uci() for x in inf['pv'][:10]], flush=True)
e.quit()
PY"}

