{"command":"python3 << 'PY'
import chess, chess.engine
e = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
e.configure({"Threads": 4, "Hash": 2048})
board = chess.Board("r1bq1rk1/p3bppB/2p4p/n2np1NQ/7P/2N5/PPPP1PP1/R1B1K2R b KQ - 3 12")
def sc(i): return i["score"].white().score(mate_score=10000)
print("legal:", [m.uci() for m in board.legal_moves])
for m in board.legal_moves:
    b=board.copy(); b.push(m)
    for d in (14,18,22):
        info=e.analyse(b, chess.engine.Limit(depth=d), multipv=3)
        print(f"=== {m.uci()} d{d}", flush=True)
        for inf in info: print("   ", sc(inf), [x.uci() for x in inf['pv'][:9]], flush=True)
e.quit()
PY"}

